using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    long long target;
    cin >> n >> target;
    // Events: +1 at start, -1 at end + 1.
    vector<pair<long long, int>> events;
    events.reserve(2 * n);
    for (int i = 0; i < n; i++) {
        long long a, b;
        cin >> a >> b;
        events.push_back({a, 1});
        events.push_back({b + 1, -1});
    }
    sort(events.begin(), events.end());
    long long active = 0, total = 0, previous = 0;
    for (auto &[t, delta] : events) {
        // `active` users each add 1 per second during [previous, t).
        long long contribution = active * (t - previous);
        if (active && total + contribution >= target) {
            cout << previous + (target - total + active - 1) / active - 1 << "\n";
            return 0;
        }
        total += contribution;
        active += delta;
        previous = t;
    }
    cout << -1 << "\n";
}

import java.io.*;
import java.util.*;

public class Main {
    static final InputStream IN = System.in;
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int readByte() throws IOException {
        if (ptr == len) {
            len = IN.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        boolean neg = c == '-';
        if (neg) c = readByte();
        long v = 0;
        while (c >= '0' && c <= '9') {
            v = v * 10 + (c - '0');
            c = readByte();
        }
        return neg ? -v : v;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = readByte();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        long target = nextLong();
        // Events packed as time * 2 + (1 for +1 at start, 0 for -1 at end + 1).
        long[] events = new long[2 * n];
        for (int i = 0; i < n; i++) {
            long a = nextLong(), b = nextLong();
            events[2 * i] = a * 2 + 1;
            events[2 * i + 1] = (b + 1) * 2;
        }
        Arrays.sort(events);
        long active = 0, total = 0, previous = 0;
        for (long e : events) {
            long t = e >> 1;
            // `active` users each add 1 per second during [previous, t).
            long contribution = active * (t - previous);
            if (active > 0 && total + contribution >= target) {
                System.out.println(previous + (target - total + active - 1) / active - 1);
                return;
            }
            total += contribution;
            active += (e & 1) == 1 ? 1 : -1;
            previous = t;
        }
        System.out.println(-1);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
	"sort"
)

var data []byte
var pos int

// token returns the next whitespace-separated token of stdin.
func token() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int {
	b := token()
	neg := len(b) > 0 && b[0] == '-'
	if neg {
		b = b[1:]
	}
	v := 0
	for _, c := range b {
		v = v*10 + int(c-'0')
	}
	if neg {
		return -v
	}
	return v
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n, target := nextInt(), nextInt()
	// Events packed as time * 2 + (1 for +1 at start, 0 for -1 at end + 1).
	events := make([]int, 0, 2*n)
	for i := 0; i < n; i++ {
		a, b := nextInt(), nextInt()
		events = append(events, a*2+1, (b+1)*2)
	}
	sort.Ints(events)
	active, total, previous := 0, 0, 0
	for _, e := range events {
		t := e >> 1
		// `active` users each add 1 per second during [previous, t).
		contribution := active * (t - previous)
		if active > 0 && total+contribution >= target {
			fmt.Println(previous + (target-total+active-1)/active - 1)
			return
		}
		total += contribution
		if e&1 == 1 {
			active++
		} else {
			active--
		}
		previous = t
	}
	fmt.Println(-1)
}
